// Stage 19: grade 11 questions written for the MEB Türkiye Yüzyılı Maarif Modeli programs (grade 11 since 2026-27).
// Source of themes and learning outcomes: the official 2026-2027 Anadolu Lisesi frame plans on tymm.meb.gov.tr
// (list for the tests: tests/data/meb11-outcomes.json). Same rules as grades 9 and 10 (see quiz-bank-meb9.ts):
// context-based questions, distractors from misconceptions, no "all/none of the above".
// Not approved by MEB: the subject teachers of the school are reviewing them.
//
// In each question below the FIRST option is the correct one; the bank moves it to a different letter.
import type { QuizDifficulty, QuizSubject } from './quiz-question-bank';
import type { MebSeed } from './quiz-bank-meb9';

/** Theme of each learning-outcome group ("11.1" = first theme), from the official frame plans. */
export const MEB11_THEMES: Record<string, Record<string, string>> = {
  MAT: {
    '11.1': 'İstatistiksel Araştırma Süreci',
    '11.2': 'Geometrik Şekiller',
    '11.3': 'Nicelikler ve Değişimler',
  },
  FİZ: {
    '11.1': 'Kuvvet ve Hareket',
    '11.2': 'Elektrik ve Manyetizma',
    '11.3': 'Optik',
  },
  KİM: {
    '11.1': 'Etkileşim',
    '11.2': 'Çeşitlilik',
    '11.3': 'Sürdürülebilirlik',
  },
  BİY: {
    '11.1': 'Tepki',
    '11.2': 'Homeostazi',
  },
};

function q(
  outcome: string,
  difficulty: QuizDifficulty,
  prompt: string,
  options: [string, string, string, string],
  explanation: string,
): MebSeed {
  const [prefix, grade, unit] = outcome.split('.');
  const theme = MEB11_THEMES[prefix]?.[`${grade}.${unit}`];
  if (!theme) throw new Error(`Unknown MEB outcome ${outcome}`);
  return { outcome, theme, difficulty, prompt, options, explanation };
}

